gcZ8(){return"\u0646\u062a\u06cc\u062c\u0647 \u062a\u0633\u062a \u0627\u062a\u0635\u0627\u0644"},
gcZ1(){return"\u062a\u0633\u062a \u0627\u062a\u0635\u0627\u0644 \u0627\u0646\u062c\u0627\u0645 \u0634\u062f"},
gcZ9(){return"\u0627\u062a\u0635\u0627\u0644 \u0628\u0647 \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u0628\u0631\u0642\u0631\u0627\u0631 \u0627\u0633\u062a"},
