gcZ3(){return"\u0627\u062d\u062a\u0645\u0627\u0644 \u0646\u0627\u0647\u0645\u0627\u0647\u0646\u06af\u06cc \u06a9\u0644\u06cc\u062f/\u06af\u0648\u0627\u0647\u06cc \u0628\u0627 \u062d\u0627\u0641\u0638\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 (\u062e\u0637\u0627\u06cc 4103)"},
gcZ6(){return"\u0627\u0637\u0644\u0627\u0639\u0627\u062a \u062a\u0648\u06a9\u0646 \u0645\u0648\u062f\u06cc\u0627\u0646"},
gcZ4(){return"\u0634\u0646\u0627\u0633\u0647 \u062d\u0627\u0641\u0638\u0647 (sub)"},
gcZ5(){return"\u0634\u0646\u0627\u0633\u0647 \u0645\u0648\u062f\u06cc (taxpayerId)"},
gcZ7(){return"\u0634\u0646\u0627\u0633\u0647 \u062d\u0627\u0641\u0638\u0647 \u062a\u0648\u06a9\u0646 \u0628\u0627 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0645\u0637\u0627\u0628\u0642\u062a \u0646\u062f\u0627\u0631\u062f"},
gcZ2(){return"\u06a9\u062f \u0627\u0642\u062a\u0635\u0627\u062f\u06cc \u062a\u0648\u06a9\u0646 \u0628\u0627 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0645\u0637\u0627\u0628\u0642\u062a \u0646\u062f\u0627\u0631\u062f"},
gbts(){return"\u0647\u0634\u062f\u0627\u0631\u0647\u0627\u06cc \u067e\u06cc\u06a9\u0631\u0628\u0646\u062f\u06cc \u0645\u0648\u062f\u06cc\u0627\u0646"},
gcXJ(){return"\u0628\u0631\u0631\u0633\u06cc \u0647\u0648\u06cc\u062a \u0627\u0645\u0636\u0627"},
gcYz(){return"\u062d\u0627\u0644\u062a Sandbox \u0641\u0639\u0627\u0644 \u0627\u0633\u062a"},
gbtG(){return"\u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc"},
gbtF(){return"\u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0648 \u06a9\u0644\u06cc\u062f\u0647\u0627\u06cc \u0627\u0631\u062a\u0628\u0627\u0637 \u0628\u0627 \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u0631\u0627 \u0645\u062f\u06cc\u0631\u06cc\u062a \u06a9\u0646\u06cc\u062f."},
gcHW(){return"\u0627\u0641\u0632\u0648\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u0641\u0639\u0627\u0644 \u0646\u06cc\u0633\u062a"},
gcHV(){return"\u0628\u0631\u0627\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0648 \u0627\u0631\u0633\u0627\u0644 \u0635\u0648\u0631\u062a\u200c\u062d\u0633\u0627\u0628 \u0628\u0647 \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646\u060c \u0627\u0641\u0632\u0648\u0646\u0647 \xab\u0627\u062a\u0635\u0627\u0644 \u0628\u0647 \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646\xbb \u0631\u0627 \u0627\u0632 \u0628\u0627\u0632\u0627\u0631 \u0627\u0641\u0632\u0648\u0646\u0647\u200c\u0647\u0627 \u0641\u0639\u0627\u0644 \u06cc\u0627 \u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u06a9\u0646\u06cc\u062f."},
gcHU(){return"\u0631\u0641\u062a\u0646 \u0628\u0647 \u0628\u0627\u0632\u0627\u0631 \u0627\u0641\u0632\u0648\u0646\u0647\u200c\u0647\u0627"},
gcHT(){return"\u0645\u0634\u0627\u0647\u062f\u0647 \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646"},
gcHS(){return"\u0627\u0631\u0633\u0627\u0644 \u0648 \u0639\u0645\u0644\u06cc\u0627\u062a \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646"},
gcHR(){return"\u0645\u062f\u06cc\u0631\u06cc\u062a \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0645\u0648\u062f\u06cc\u0627\u0646"},
